let tab='ficha',route='agentes',campaignTab='agentes',activeCombatId='',mesaTab='agentes',homebrewTab='Ameaças',threatFilter='',bookUrl=null,books={},bookCovers={},officialThreats=[],threatSource='todos',catalogData={entries:[],sources:[]},revision=0,loaded=false,saving=false,pending=false,saveTimer=null,catalogPage=0,guestMode=false,agentListOpen=false,pickerMode='ability',pickerSource='',pickerElement='',pickerCircle=0,pickerClass='',activeShared='',sharedCampaign=null,sharedRevision=0,appearanceCampaignId='';
async function api(path,options={}){if(guestMode&&!path.startsWith('/api/shared')&&path!=='/api/catalog'){if(path==='/api/state'){if(options.method==='PUT'){const data=JSON.parse(options.body);localStorage.setItem('limiar-guest-state',JSON.stringify(data.state));return{revision:data.revision+1};}return{state:JSON.parse(localStorage.getItem('limiar-guest-state')||'null'),revision:0};}if(path==='/api/books'&&(!options.method||options.method==='GET'))return{};throw Error('Esta função precisa da sua conta no site.');}const response=await fetch(path,{...options,headers:{...options.headers},credentials:'same-origin'});let data;try{data=await response.json();}catch{throw Error('O servidor não respondeu. Tente novamente.');}if(!response.ok){const error=Error(data.error||'Não foi possível salvar.');error.status=response.status;throw error;}return data;}
function syncStatus(text){const el=document.querySelector('#sync-status');if(el)el.textContent=text;}
function save(){pending=true;clearTimeout(saveTimer);saveTimer=setTimeout(flushSave,350);syncStatus('Alterações pendentes…');}
async function flushSave(){if(saving||!loaded)return;if(!pending)return;saving=true;pending=false;syncStatus('Salvando…');const snapshot=JSON.stringify({state,revision});try{const result=await api('/api/state',{method:'PUT',headers:{'Content-Type':'application/json'},body:snapshot});revision=result.revision;storageOk=true;syncStatus(guestMode?'Salvo neste navegador':'Salvo na sua conta');}catch(error){pending=true;storageOk=false;syncStatus('Falha ao salvar · tente novamente');toast(error.message);saving=false;return;}saving=false;if(pending)await flushSave();}
async function boot(){loaded=false;document.querySelector('#app').innerHTML='<div class="panel empty">Abrindo seu arquivo…</div>';try{const [data,cat]=await Promise.all([api('/api/state'),api('/api/catalog')]);await loadReferenceAssets();if(data.state)state=validateBackup({version:1,...data.state});revision=data.revision;catalogData=cat;loaded=true;storageOk=true;render();syncStatus('Salvo na sua conta');initBooks();if(/^#campanhas\/[A-Fa-f0-9]{20}(?:\/|$)/.test(location.hash))openShared(location.hash.split('/')[1]);}catch(error){if(error.status===401){try{guestMode=true;document.body.classList.add('guest');const [local,guestCatalog]=await Promise.all([api('/api/state'),api('/api/catalog')]);catalogData=guestCatalog;await loadReferenceAssets();if(local.state)state=validateBackup({version:1,...local.state});revision=local.revision;loaded=true;storageOk=true;render();syncStatus('Salvo neste navegador');if(/^#campanhas\/[A-Fa-f0-9]{20}(?:\/|$)/.test(location.hash))openShared(location.hash.split('/')[1]);return;}catch(localError){guestMode=false;document.body.classList.remove('guest');error=localError;}}document.querySelector('#app').innerHTML='<div class="panel empty"><h2>Não foi possível abrir o arquivo</h2><p>'+esc(error.message)+'</p><button class="button primary" data-action="retry-load">Tentar novamente</button></div>';}}

async function loadReferenceAssets(){try{const [covers,threats]=await Promise.all([fetch('/book-covers.json'),fetch('/threats.json')]);if(covers.ok)bookCovers=await covers.json();if(threats.ok)officialThreats=await threats.json();}catch(e){console.warn('Referências indisponíveis',e);}}
