appearance=function appearanceWithGlobalSkin(){const pref=state.appearance&&typeof state.appearance==='object'?state.appearance:{};pref.sheet=pref.sheet||'padrao';pref.profile=pref.profile||'padrao';if(!skins.some(([id])=>id===pref.site))pref.site=skins.some(([id])=>id===pref.sheet)?pref.sheet:'padrao';state.appearance=pref;return pref;};
