function campaignOperationNames(op,c,local){
 if(Array.isArray(op.crew)&&op.crew.length)return op.crew.map(x=>({id:x.id,name:x.name,meta:x.meta}));
 const chosen=new Set(op.agentIds||[]),result=[];
 for(const id of local.agents||[]){const a=state.agents.find(x=>x.id===id);if(chosen.has('agent:'+id)&&a)result.push({id:'agent:'+id,name:a.name,meta:`${a.class} · NEX ${a.nex}%`});}
 for(const p of c.roster||[]){if(chosen.has('member:'+p.id))result.push({id:'member:'+p.id,name:p.agent||p.name,meta:`Jogador: ${p.name}`});}
 return result;
}
