function muralBoardList(local,c){const current=Array.isArray(c?.murals)?c.murals:[],old=c?.mural||{},privateOld=local?.isMaster!==false?local?.muralPrivate||{}:{};const hasLegacy=!old.deleted&&((old.cards||[]).length||(old.links||[]).length||(privateOld.cards||[]).length||(privateOld.links||[]).length);return[...(hasLegacy?[{...old,id:legacyMuralId,title:old.title||'Mural inicial',description:old.description||'Cartões criados antes da organização em murais.'}]:[]),...current.filter(x=>x&&x.id&&x.title)];}
function muralPublicData(c,id=activeMuralId){if(id===legacyMuralId){if(!c.mural||typeof c.mural!=='object')c.mural={cards:[],links:[]};return c.mural;}return(c.murals||[]).find(x=>x.id===id);}
function muralPrivateData(local,id=activeMuralId){if(!local.muralPrivate||typeof local.muralPrivate!=='object')local.muralPrivate={cards:[],links:[]};if(id===legacyMuralId)return local.muralPrivate;if(!local.muralPrivate.boards||typeof local.muralPrivate.boards!=='object')local.muralPrivate.boards={};return local.muralPrivate.boards[id]||(local.muralPrivate.boards[id]={cards:[],links:[]});}
function muralSnapshot(local,c,id=activeMuralId){const master=local?.isMaster!==false,publicData=id===legacyMuralId?c?.mural:(c?.murals||[]).find(x=>x.id===id)||{},privateData=master?(id===legacyMuralId?local?.muralPrivate:local?.muralPrivate?.boards?.[id])||{}:{},publicCards=Array.isArray(publicData?.cards)?publicData.cards.filter(x=>x&&!x.secret&&x.visibility!=='secret').map(x=>({...x,secret:false})):[],privateCards=Array.isArray(privateData.cards)?privateData.cards.filter(Boolean).map(x=>({...x,secret:true})):[],cards=[...publicCards,...privateCards],ids=new Set(cards.map(x=>x.id)),publicLinks=Array.isArray(publicData?.links)?publicData.links.filter(x=>x&&!x.secret&&ids.has(x.from)&&ids.has(x.to)).map(x=>({...x,secret:false})):[],privateLinks=Array.isArray(privateData.links)?privateData.links.filter(x=>x&&ids.has(x.from)&&ids.has(x.to)).map(x=>({...x,secret:true})):[];return{master,cards,links:[...publicLinks,...privateLinks]};}
function muralPrivateMutate(change){const local=campaignLocal();if(!local||local.isMaster===false||!activeMuralId)return;const data=muralPrivateData(local);if(!Array.isArray(data.cards))data.cards=[];if(!Array.isArray(data.links))data.links=[];change(data);save();render();}
