function editMuralBoard(id=''){const c=campaignCurrent(),old=muralBoardList(campaignLocal(),c).find(x=>x.id===id);modal(id?'Editar mural':'Novo mural',`<div class="form-grid">${field('title','Nome do mural',old?.title||'','text','required maxlength="120"')}<label class="field full">Descrição<textarea name="description" rows="3" maxlength="500" placeholder="Qual investigação pertence a este mural?">${esc(old?.description||'')}</textarea></label></div>`,f=>{const title=String(f.get('title')||'').trim(),description=String(f.get('description')||'').trim();if(!title)throw Error('Informe o nome do mural.');if(id===legacyMuralId)campaignMutate(c=>Object.assign(muralPublicData(c,id),{title,description}));else if(id)campaignMutate(c=>{const board=(c.murals||[]).find(x=>x.id===id);if(board)Object.assign(board,{title,description});});else{const newId=uid();activeMuralId=newId;campaignMutate(c=>{c.murals ||= [];c.murals.push({id:newId,title,description,cards:[],links:[]});});}});}
