function muralCamera(){const key=(campaignLocal()?.id||'')+':'+activeMuralId;if(!muralCameras.has(key))muralCameras.set(key,{x:0,y:0,scale:1});return muralCameras.get(key);}
function muralApplyCamera(){const canvas=document.querySelector('.mural-canvas');if(!canvas)return;const view=muralCamera();canvas.style.transform=`translate(${view.x}px,${view.y}px) scale(${view.scale})`;const stage=canvas.closest('.mural-stage-scroll');stage.style.setProperty('--mural-x',view.x+'px');stage.style.setProperty('--mural-y',view.y+'px');stage.style.setProperty('--mural-scale',view.scale);const label=document.querySelector('#mural-zoom-level');if(label)label.textContent=Math.round(view.scale*100)+'%';}
function muralZoomAt(factor,clientX,clientY){const stage=document.querySelector('.mural-stage-scroll');if(!stage)return;const camera=muralCamera(),box=stage.getBoundingClientRect(),px=clientX-box.left,py=clientY-box.top,scale=Math.max(.15,Math.min(3,camera.scale*factor));camera.x=px-(px-camera.x)*scale/camera.scale;camera.y=py-(py-camera.y)*scale/camera.scale;camera.scale=scale;muralApplyCamera();}
function muralFitCards(){const stage=document.querySelector('.mural-stage-scroll'),local=campaignLocal(),c=campaignCurrent();if(!stage||!local||!c)return;const cards=muralSnapshot(local,c).cards,camera=muralCamera();if(!cards.length){Object.assign(camera,{x:0,y:0,scale:1});return muralApplyCamera();}const minX=Math.min(...cards.map(v=>Number(v.x)||0)),minY=Math.min(...cards.map(v=>Number(v.y)||0)),maxX=Math.max(...cards.map(v=>(Number(v.x)||0)+250)),maxY=Math.max(...cards.map(v=>(Number(v.y)||0)+180)),margin=42;camera.scale=Math.max(.15,Math.min(1,(stage.clientWidth-margin*2)/Math.max(250,maxX-minX),(stage.clientHeight-margin*2)/Math.max(180,maxY-minY)));camera.x=(stage.clientWidth-(maxX-minX)*camera.scale)/2-minX*camera.scale;camera.y=(stage.clientHeight-(maxY-minY)*camera.scale)/2-minY*camera.scale;muralApplyCamera();}
function muralCardPosition(index){const stage=document.querySelector('.mural-stage-scroll');if(!stage)return{x:30+(index%4)*340,y:35+Math.floor(index/4)*225};const camera=muralCamera();return{x:Math.round((stage.clientWidth/2-camera.x)/camera.scale-125+(index%3)*20),y:Math.round((stage.clientHeight/2-camera.y)/camera.scale-90+(index%3)*20)};}
function muralEdgePoints(a,b){const dx=b.x-a.x,dy=b.y-a.y,scale=1/Math.max(Math.abs(dx)/125,Math.abs(dy)/90,0.0001);return{x1:a.x+dx*scale,y1:a.y+dy*scale,x2:b.x-dx*scale,y2:b.y-dy*scale};}
function muralRenderBoard(local,c){const board=muralSnapshot(local,c),cards=board.cards,camera=muralCamera(),byId=new Map(cards.map(x=>[x.id,x])),xy=x=>({x:Number(x.x)||0,y:Number(x.y)||0}),icon={Pessoa:'◉',Local:'⌖',Criatura:'♧',Documento:'▤',Ritual:'✧',Evento:'◷',Objeto:'◇'};const edgeMarkup=board.links.map(link=>{const from=byId.get(link.from),to=byId.get(link.to);if(!from||!to)return'';const a=xy(from),b=xy(to),p=muralEdgePoints({x:a.x+125,y:a.y+90},{x:b.x+125,y:b.y+90}),{x1,y1,x2,y2}=p,mx=(x1+x2)/2,my=(y1+y2)/2;return `<g class="mural-edge ${link.secret?'is-secret':''}" data-mural-edge="${esc(link.id)}" data-from="${esc(link.from)}" data-to="${esc(link.to)}"><line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" marker-end="url(#mural-arrow)"/><text class="mural-edge-label" x="${mx}" y="${my-8}" text-anchor="middle">${esc(link.relation)}</text></g>`;}).join('');const cardMarkup=cards.map(card=>{const p=xy(card),secret=!!card.secret,ref=muralReference(card);return `<article class="mural-card ${secret?'is-secret':''}" data-mural-card="${esc(card.id)}" data-mural-private="${secret?'1':'0'}" style="left:${p.x}px;top:${p.y}px"><div class="mural-card-top"><span class="mural-kind kind-${String(card.kind||'Objeto').toLowerCase()}">${icon[card.kind]||'◇'} ${esc(card.kind||'Objeto')}</span>${secret?'<span class="mural-secret-tag">SEGREDO</span>':''}</div><h3>${esc(card.title)}</h3><p>${esc(card.body||'Sem anotação.').replace(/\n/g,'<br>')}</p>${ref?`<div class="mural-card-ref">${button(esc(ref.label)+(ref.available?' ↗':' · referência indisponível'),'mural-open-reference','small ghost',`data-id="${esc(card.id)}" ${ref.available?'':'disabled'}`)}</div>`:''}<div class="mural-card-actions">${button('Ligar ⤴','mural-connect-from','small ghost mural-connect-handle',`data-id="${esc(card.id)}" aria-label="Arraste para conectar ${esc(card.title)} a outro cartão"`)}${button('Editar','mural-edit-card','small ghost',`data-id="${esc(card.id)}" data-secret="${secret?'1':'0'}"`)}${button('Excluir','mural-delete-card','small ghost',`data-id="${esc(card.id)}" data-secret="${secret?'1':'0'}"`)}</div></article>`;}).join('');const linksList=board.links.map(link=>{const from=byId.get(link.from),to=byId.get(link.to);if(!from||!to)return'';return `<div class="mural-link-row"><span>${esc(from.title)}</span>${button(esc(link.relation),"mural-edit-link","small ghost mural-link-label",`data-id="${esc(link.id)}" data-secret="${link.secret?"1":"0"}" aria-label="Editar relação entre ${esc(from.title)} e ${esc(to.title)}"`)}<span>${esc(to.title)}</span>${link.secret?'<small class="mural-secret-tag">SEGREDO</small>':''}${button('×','mural-delete-link','small ghost',`data-id="${esc(link.id)}" data-secret="${link.secret?'1':'0'}" aria-label="Remover conexão"`)}</div>`;}).join('');return `<div class="mural-page"><div class="mural-intro"><div><span class="eyebrow">QUADRO DE PISTAS / CAMPANHA</span><h2>${esc(muralBoardList(local,c).find(x=>x.id===activeMuralId)?.title||"Mural")}</h2><p>Arraste o fundo para explorar o mural sem bordas. Use o zoom e arraste os cartões livremente. Para conectar, arraste “Ligar” até outro cartão.</p></div><div class="actions">${button('+ Novo cartão','mural-add-card','small primary')}</div></div><div id="mural-link-status" class="notice mural-link-status" hidden></div><div class="notice mural-privacy">${board.master?'<b>Segredos do mestre:</b> ficam no arquivo pessoal do mestre e não são enviados à campanha compartilhada.':'Este mural mostra apenas cartões compartilhados. Os segredos privados do mestre não aparecem para jogadores.'}</div>${!cards.length?`<div class="panel mural-empty"><span>⌕</span><h3>O quadro ainda está vazio</h3><p>Crie o primeiro cartão para começar a ligar as pistas.</p>${button('＋ Criar primeiro cartão','mural-add-card','small primary')}</div>`:''}<div class="mural-view-controls">${button('−','mural-zoom-out','small ghost',`aria-label="Diminuir zoom"`)}<span id="mural-zoom-level">${Math.round(camera.scale*100)}%</span>${button('+','mural-zoom-in','small ghost',`aria-label="Aumentar zoom"`)}${button('Enquadrar cartões','mural-fit','small ghost')}</div><div class="mural-stage-scroll" style="--mural-x:${camera.x}px;--mural-y:${camera.y}px;--mural-scale:${camera.scale}" aria-label="Mural sem bordas; arraste o fundo para navegar"><div class="mural-canvas" style="transform:translate(${camera.x}px,${camera.y}px) scale(${camera.scale})"><svg class="mural-lines" aria-hidden="true"><defs><marker id="mural-arrow" markerWidth="10" markerHeight="10" refX="8" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8 Z"></path></marker></defs>${edgeMarkup}</svg>${cardMarkup}</div></div><div class="mural-connections"><div class="section-title"><h3>Conexões do quadro</h3><span class="meta">${board.links.length} ligação${board.links.length===1?'':'ões'}</span></div>${linksList||'<p class="hint">Ainda não há conexões. Crie ao menos dois cartões e ligue as informações.</p>'}</div></div>`;}
function editMuralCard(id='',isPrivate=false){
 const local=campaignLocal(),c=campaignCurrent();if(!local||!c||!activeMuralId)return;
 const board=muralSnapshot(local,c),existing=board.cards.find(x=>x.id===id),position=existing?{x:Number(existing.x)||0,y:Number(existing.y)||0}:muralCardPosition(board.cards.length);
 if(isPrivate&&local.isMaster===false)return toast('Este segredo pertence ao mestre.');
 const visibility=!id&&local.isMaster!==false?`<div class="mural-secret-choice">${check('secret','Segredo do mestre · fica fora da campanha compartilhada',false)}</div>`:existing?.secret?'<div class="notice">Este cartão é privado e só aparece no arquivo do mestre.</div>':'';
 const agents=(existing?.refKind==='agent'&&existing.refId&&!state.agents.some(x=>x.id===existing.refId)?`<option value="${esc(existing.refId)}" selected>${esc(existing.refName||existing.title)} · indisponível neste arquivo</option>`:'')+state.agents.map(x=>`<option value="${esc(x.id)}" ${existing?.refKind==='agent'&&existing.refId===x.id?'selected':''}>${esc(x.name)}</option>`).join('');
 const threats=(existing?.refKind==='threat'&&existing.refId&&!muralThreats().some(x=>x.id===existing.refId)?`<option value="${esc(existing.refId)}" selected>${esc(existing.refName||existing.title)} · indisponível neste arquivo</option>`:'')+muralThreats().map(x=>`<option value="${esc(x.id)}" ${existing?.refKind==='threat'&&existing.refId===x.id?'selected':''}>${esc(x.name)}${x.vd?' · VD '+esc(x.vd):''}</option>`).join('');
 modal(existing?'Editar cartão':'Novo cartão',`<div class="form-grid">${field('title','Título',existing?.title||'','text','required maxlength="120"')}${select('kind','Tipo de registro',muralKinds,existing?.kind||'Pessoa')}<label class="field full" data-mural-ref-kind="Pessoa" ${existing&&existing.kind!=='Pessoa'?'hidden':''}>Ficha vinculada (opcional)<select name="agentRef"><option value="">Sem ficha vinculada</option>${agents}</select></label><label class="field full" data-mural-ref-kind="Criatura" ${existing?.kind!=='Criatura'?'hidden':''}>Ameaça vinculada (opcional)<select name="threatRef"><option value="">Sem ameaça vinculada</option>${threats}</select></label><label class="field full">Informações<textarea name="body" rows="5" maxlength="5000" placeholder="Anote a pista, contexto ou detalhe importante…">${esc(existing?.body||'')}</textarea></label>${visibility}</div>`,f=>{
  const title=String(f.get('title')||'').trim(),kind=String(f.get('kind')||'Pessoa');if(!title)throw Error('Dê um título para o cartão.');
  const refKind=kind==='Pessoa'?'agent':kind==='Criatura'?'threat':'',refId=refKind?String(f.get(refKind==='agent'?'agentRef':'threatRef')||''):'';
  const refItem=refKind==='agent'?state.agents.find(x=>x.id===refId):refKind==='threat'?muralThreats().find(x=>x.id===refId):null;
  const preservedRef=existing?.refKind===refKind&&existing?.refId===refId?existing:null;const card={id:id||uid(),title,kind,body:String(f.get('body')||'').trim(),x:position.x,y:position.y,refKind:refItem||preservedRef?refKind:'',refId:refItem?.id||preservedRef?.refId||'',refName:refItem?.name||preservedRef?.refName||''};
  const secret=existing?!!existing.secret:local.isMaster!==false&&f.has('secret');
  if(secret)muralPrivateMutate(data=>{const target=data.cards.find(x=>x.id===card.id);if(target)Object.assign(target,card);else data.cards.push(card);});
  else muralPublicMutate(data=>{const target=data.cards.find(x=>x.id===card.id);if(target)Object.assign(target,card);else data.cards.push(card);});
 });
}
function addMuralLink(from,to,id='',isPrivate=false){
 const local=campaignLocal(),c=campaignCurrent();if(!local||!c||!activeMuralId)return;
 const board=muralSnapshot(local,c),a=board.cards.find(x=>x.id===from),b=board.cards.find(x=>x.id===to),existing=board.links.find(x=>x.id===id);
 if(!a||!b||from===to)return toast('Escolha dois cartões diferentes.');
 modal(existing?'Editar conexão':'Nova conexão',`<p class="hint"><b>${esc(a.title)}</b> → <b>${esc(b.title)}</b></p>${field('relation','O que liga esses cartões?',existing?.relation||'relacionado a','text','required maxlength="160" placeholder="Ex.: foi visto no local do ritual"')}`,f=>{
  const relation=String(f.get('relation')||'').trim();if(!relation)throw Error('Descreva a conexão.');
  if(existing){const mutate=existing.secret?muralPrivateMutate:muralPublicMutate;mutate(data=>{const target=data.links.find(x=>x.id===id);if(target)target.relation=relation;});}
  else{const link={id:uid(),from,to,relation};if(a.secret||b.secret)muralPrivateMutate(data=>data.links.push(link));else muralPublicMutate(data=>data.links.push(link));}
 });
}
function editMuralLink(id){const board=muralSnapshot(campaignLocal(),campaignCurrent()),link=board.links.find(x=>x.id===id);if(link)addMuralLink(link.from,link.to,id,!!link.secret);}
function openMuralReference(id){const card=muralSnapshot(campaignLocal(),campaignCurrent()).cards.find(x=>x.id===id),ref=card&&muralReference(card);if(!ref?.available)return toast('Esta referência não está disponível neste arquivo.');if(card.refKind==='agent'){state.selected=card.refId;save();location.hash='agentes';render();}else if(card.refKind==='threat'){threatFilter=ref.label;threatSource='todos';location.hash='ameacas';render();}}
function deleteMuralCard(id,isPrivate){modal('Excluir cartão?','<p>O cartão e as conexões ligadas a ele serão removidos do mural.</p>',()=>{const local=campaignLocal();if(isPrivate)muralPrivateMutate(data=>{data.cards=data.cards.filter(x=>x.id!==id);data.links=data.links.filter(x=>x.from!==id&&x.to!==id);});else{muralPublicMutate(data=>{data.cards=data.cards.filter(x=>x.id!==id);data.links=data.links.filter(x=>x.from!==id&&x.to!==id);});if(local?.isMaster!==false&&(activeMuralId===legacyMuralId?local?.muralPrivate?.links:local?.muralPrivate?.boards?.[activeMuralId]?.links)?.some(x=>x.from===id||x.to===id))muralPrivateMutate(data=>{data.links=data.links.filter(x=>x.from!==id&&x.to!==id);});}});}
function deleteMuralLink(id,isPrivate){const local=campaignLocal();if(isPrivate)muralPrivateMutate(data=>{data.links=data.links.filter(x=>x.id!==id);});else muralPublicMutate(data=>{data.links=data.links.filter(x=>x.id!==id);});}
function muralRefreshEdges(canvas){const svg=canvas?.querySelector('.mural-lines');if(!svg)return;svg.setAttribute('viewBox',`0 0 ${canvas.clientWidth} ${canvas.clientHeight}`);const cards=[...canvas.querySelectorAll('[data-mural-card]')],find=id=>cards.find(x=>x.dataset.muralCard===id);for(const edge of svg.querySelectorAll('[data-mural-edge]')){const a=find(edge.dataset.from),b=find(edge.dataset.to);if(!a||!b)continue;const line=edge.querySelector('line'),label=edge.querySelector('text'),p=muralEdgePoints({x:a.offsetLeft+a.offsetWidth/2,y:a.offsetTop+a.offsetHeight/2},{x:b.offsetLeft+b.offsetWidth/2,y:b.offsetTop+b.offsetHeight/2}),{x1,y1,x2,y2}=p;line.setAttribute('x1',x1);line.setAttribute('y1',y1);line.setAttribute('x2',x2);line.setAttribute('y2',y2);label.setAttribute('x',(x1+x2)/2);label.setAttribute('y',(y1+y2)/2-8);}}
function renderMuralBoard(local,c){const boards=muralBoardList(local,c),selected=boards.find(x=>x.id===activeMuralId);if(!selected){activeMuralId='';return `<div class="mural-wrap mural-page"><div class="mural-intro"><div><span class="eyebrow">ARQUIVO / CAMPANHA</span><h2>Murais de investigação</h2><p>Crie um mural para cada caso ou linha de investigação. Abra um mural para organizar cartões e conexões.</p></div>${button('+ Novo mural','mural-create','small primary')}</div>${boards.length?`<div class="mural-board-grid">${boards.map(x=>{const data=muralSnapshot(local,c,x.id);return `<article class="panel mural-board-tile"><span class="eyebrow">QUADRO DE PISTAS</span><h3>${esc(x.title)}</h3><p>${esc(x.description||'Sem descrição.')}</p><small>${data.cards.length} cartão(ões) · ${data.links.length} conexão(ões)</small><div class="actions">${button('Abrir mural ↗','mural-open','small primary',`data-id="${esc(x.id)}"`)}${button('Editar','mural-edit-board','small ghost',`data-id="${esc(x.id)}"`)}${button('Excluir','mural-delete-board','small ghost',`data-id="${esc(x.id)}"`)}</div></article>`;}).join('')}</div>`:`<div class="panel mural-empty"><span>⌕</span><h3>Nenhum mural criado</h3><p>Crie um mural para começar a organizar as pistas desta campanha.</p>${button('＋ Criar mural','mural-create','small primary')}</div>`}</div>`;}return `<div class="mural-wrap mural-page"><div class="mural-board-nav">${button('‹ Todos os murais','mural-back','small ghost')}<span class="eyebrow">${esc(selected.title)}</span></div>${muralRenderBoard(local,c)}</div>`;}
function campaignOperationsPage(local,c,agents){
 const operations=operationEntries(c,'operations'),active=operations.find(x=>x.id===activeOperationId);
 const shared=!!local.shareCode;
 const tabs=[['agentes','Agentes',agents.length],['jogadores','Jogadores',(c.roster||[]).length],['combates','Combates',(c.combats||[]).length],['operacoes','Operações',operations.length],['pistas','Pistas',campaignClues(c).length],['mural','Mural',muralBoardList(local,c).length]];
 const tabBar=`<div class="tabs campaign-subtabs">${tabs.map(([id,label,count])=>`<button class="${campaignTab===id?'active':''}" data-action="campaign-section" data-tab="${id}">${label} <small>${count}</small></button>`).join('')}</div>`;
 const toolbar=`<div class="campaign-toolbar">${button('Escudo do Mestre','campaign-play','small primary')}${button('Adicionar agentes','campaign-add-agents','small ghost')}${button(shared?'Copiar convite':'Convidar jogadores',shared?'shared-copy':'shared-create','small ghost',`data-id="${local.id}"`)}${button('Editar campanha','edit-campaign','small ghost',`data-id="${local.id}"`)}${button('Criar combate','campaign-new-combat','small ghost')}</div>`;
 const hero=`<header class="campaign-hero"><div class="campaign-cover-detail"><span>ARQUIVO LIMIAR / CAMPANHA</span><b>${esc(c.name)}</b></div><div class="campaign-hero-info"><span class="badge muted">${esc(c.mode||'Regras da mesa')}</span><h1>${esc(c.name)}</h1><p>${esc(c.notes||'A história desta campanha começa aqui.')}</p><small>SESSÃO ${c.session} · ${esc(c.status)} ${shared?'· MESA COMPARTILHADA':'· ARQUIVO PESSOAL'}</small></div></header>`;
 const invite=shared?`<div class="campaign-invite"><label>LINK PARA OS JOGADORES<input id="shared-link" readonly value="${esc(inviteLink(local.shareCode))}"></label>${button('Copiar','shared-copy','small primary')}${button('Atualizar','shared-refresh','small ghost')}</div>`:'';
 if(campaignTab==='mural')setTimeout(()=>muralRefreshEdges(document.querySelector('.mural-canvas')),0);
 const content=campaignTab==='mural'?renderMuralBoard(local,c):campaignTab==='pistas'?renderClueRegistry(local,c):active?renderOperation(active,c,local):renderOperationList(operations);
 return `<div class="campaign-detail" id="campaign-detail"><button class="back-link" data-action="campaign-back">‹ Todas as campanhas</button>${toolbar}${hero}${invite}${tabBar}<div class="campaign-section operation-section">${content}</div></div>`;
}
function renderOperationList(operations){
 return `<div class="operation-list-head"><div><span class="eyebrow">MISSÕES / INVESTIGAÇÕES</span><h2>Painel de operações</h2><p>Reúna o briefing, a equipe e as descobertas de cada missão num só lugar.</p></div>${button('+ Nova operação','operation-create','small primary')}</div>${operations.length?`<div class="operation-grid">${operations.map(o=>`<article class="panel operation-card"><div class="operation-card-top"><span class="eyebrow">${esc(o.code||'OPERAÇÃO')}</span><span class="operation-status">${esc(o.status||'Planejada')}</span></div><button class="operation-card-open" data-action="operation-open" data-id="${esc(o.id)}"><strong>${esc(o.title)}</strong><span>${esc(o.location||'Local não definido')} · ${esc(o.date||'Data não definida')}</span><p>${esc(o.summary||'Briefing ainda não registrado.')}</p></button><div class="operation-card-foot"><span>RISCO ${esc(o.risk||'Não definido')}</span><span>${(o.agentIds||[]).length} designado(s)</span>${button('Abrir operação ↗','operation-open','small ghost',`data-id="${esc(o.id)}"`)}</div></article>`).join('')}</div>`:`<div class="panel operation-empty"><span class="operation-empty-mark">◇</span><h3>Nenhuma operação registrada</h3><p>Crie um caso para separar o briefing, os agentes, as pistas e os registros da missão.</p></div>`}`;
}
function renderOperation(op,c,local){
 const agents=campaignOperationNames(op,c,local),overview=operationTab==='overview';
 const counts={clues:campaignClues(c).filter(x=>x.operationId===op.id).length,npcs:(op.npcs||[]).length,creatures:(op.creatures||[]).length,documents:(op.documents||[]).length,timeline:(op.timeline||[]).length};
 const tabs=operationTabNames.map(([id,label])=>`<button class="${operationTab===id?'active':''}" data-action="operation-tab" data-tab="${id}">${label}${counts[id]!==undefined?` <small>${counts[id]}</small>`:''}</button>`).join('');
 const objectives=(op.objectives||[]).map(x=>`<label class="operation-objective ${x.done?'done':''}"><input type="checkbox" data-operation-objective="${esc(x.id)}" ${x.done?'checked':''}><span>${esc(x.text)}</span></label>`).join('')||'<p class="hint">Adicione os objetivos ao editar o briefing.</p>';
 const overviewContent=`<div class="operation-overview-grid"><section class="panel operation-brief"><div class="operation-panel-head"><div><span class="eyebrow">BRIEFING</span><h3>Resumo da missão</h3></div>${button('Editar briefing','operation-edit','small ghost',`data-id="${esc(op.id)}"`)}</div><p class="operation-summary">${esc(op.summary||'O mestre ainda não registrou o resumo desta operação.')}</p><div class="operation-objectives"><div class="operation-panel-head"><h3>Objetivos</h3><span class="meta">${(op.objectives||[]).filter(x=>x.done).length}/${(op.objectives||[]).length} concluídos</span></div>${objectives}</div></section><section class="panel operation-facts"><span class="eyebrow">DADOS DO CASO</span><dl><div><dt>Código</dt><dd>${esc(op.code||'—')}</dd></div><div><dt>Local</dt><dd>${esc(op.location||'Não definido')}</dd></div><div><dt>Data</dt><dd>${esc(op.date||'Não definida')}</dd></div><div><dt>Risco</dt><dd>${esc(op.risk||'Não definido')}</dd></div><div><dt>Status</dt><dd>${esc(op.status||'Planejada')}</dd></div><div><dt>Mestre</dt><dd>${esc(op.master||'Não definido')}</dd></div></dl><button class="button small ghost" data-action="operation-edit" data-id="${esc(op.id)}">Editar dados do caso</button></section><section class="panel operation-team"><div class="operation-panel-head"><div><span class="eyebrow">EQUIPE DESIGNADA</span><h3>Agentes</h3></div><button class="button small ghost" data-action="operation-tab" data-tab="agents">Ver equipe ↗</button></div>${agents.map(a=>`<div class="operation-agent-line"><span class="operation-agent-mark">${esc(a.name.slice(0,1).toUpperCase())}</span><div><strong>${esc(a.name)}</strong><small>${esc(a.meta)}</small></div></div>`).join('')||'<p class="hint">Nenhum agente foi designado. Edite o briefing para escolher a equipe.</p>'}</section><section class="panel operation-quick-links"><span class="eyebrow">REGISTROS DO CASO</span><div>${[['clues','Pistas'],['npcs','NPCs'],['creatures','Criaturas'],['documents','Documentos'],['timeline','Linha do tempo']].map(([key,label])=>`<button data-action="operation-tab" data-tab="${key}"><b>${counts[key]}</b><span>${label}</span><i>↗</i></button>`).join('')}</div></section></div>`;
 let tabContent=overviewContent;
 if(operationTab==='agents')tabContent=`<div class="operation-list-head"><div><span class="eyebrow">EQUIPE DESIGNADA</span><h2>Agentes envolvidos</h2><p>Os agentes são vinculados ao editar o briefing da operação.</p></div>${button('Editar equipe','operation-edit','small primary',`data-id="${esc(op.id)}"`)}</div><div class="operation-agent-grid">${agents.map(a=>`<article class="panel operation-agent-card"><span class="operation-agent-mark">${esc(a.name.slice(0,1).toUpperCase())}</span><div><strong>${esc(a.name)}</strong><small>${esc(a.meta)}</small></div></article>`).join('')||'<div class="panel operation-empty"><h3>Equipe não definida</h3><p>Escolha os agentes e jogadores no briefing desta missão.</p></div>'}</div>`;
 if(operationTab==='clues')tabContent=renderOperationClues(op,c,local);
 if(['npcs','creatures','documents','timeline'].includes(operationTab))tabContent=renderOperationRecords(op,operationTab);
 return `<div class="operation-detail"><div class="operation-detail-top"><button class="back-link" data-action="operation-back">‹ Todas as operações</button><div class="actions">${button('Editar caso','operation-edit','small ghost',`data-id="${esc(op.id)}"`)}${button('Excluir','operation-delete','small ghost',`data-id="${esc(op.id)}"`)}</div></div><header class="operation-hero"><div class="operation-code-block"><span>CASO</span><strong>${esc(op.code||'OP')}</strong><i>◇</i></div><div class="operation-title-block"><div class="operation-badges"><span class="operation-status">${esc(op.status||'Planejada')}</span><span class="operation-risk risk-${String(op.risk||'').toLowerCase()}">RISCO ${esc(op.risk||'—')}</span></div><h2>${esc(op.title)}</h2><p>${esc(op.location||'Local não definido')} <span>·</span> ${esc(op.date||'Data não definida')} <span>·</span> Mestre ${esc(op.master||'—')}</p></div></header><div class="tabs operation-tabs" role="tablist">${tabs}</div><div class="operation-tab-content">${tabContent}</div></div>`;
}
function safeOperationUrl(value){try{const u=new URL(value);return['http:','https:'].includes(u.protocol)?u.href:'';}catch{return'';}}
function renderOperationRecords(op,key){
 const items=[...operationEntries(op,key)];if(key==='timeline')items.sort((a,b)=>(a.when?0:1)-(b.when?0:1)||(a.when||'').localeCompare(b.when||''));const label=operationRecordNames[key],add=button(`+ Adicionar ${key==='npcs'?'NPC':key==='creatures'?'criatura':key==='documents'?'documento':key==='timeline'?'evento':'pista'}`,'operation-add-entry','small primary',`data-kind="${key}"`),linkThreat=key==='creatures'?button('Vincular do catálogo','operation-import-threat','small ghost'):'';
 return `<div class="operation-list-head"><div><span class="eyebrow">ARQUIVO DO CASO</span><h2>${label}</h2><p>${key==='clues'?'Registre evidências, origem e estado da análise.':key==='npcs'?'Acompanhe contatos, testemunhas e pessoas relevantes.':key==='creatures'?'Registre ameaças encontradas e seu estado na investigação.':key==='documents'?'Guarde relatórios, referências e documentos da missão.':'Registre acontecimentos em ordem cronológica.'}</p></div><div class="actions">${linkThreat}${add}</div></div>${items.length?`<div class="operation-record-list">${items.map(x=>{const href=key==='documents'?safeOperationUrl(x.reference):'';return `<article class="panel operation-record"><div class="operation-record-mark">${key==='clues'?'⌕':key==='npcs'?'◉':key==='creatures'?'♧':key==='documents'?'▤':'◷'}</div><div class="operation-record-main"><div class="operation-record-title"><div><span class="eyebrow">${esc(x.status||x.source||x.role||x.element||x.when||label)}</span><h3>${esc(x.title)}</h3></div><div class="actions">${button('Editar','operation-edit-entry','small ghost',`data-kind="${key}" data-id="${esc(x.id)}"`)}${button('Excluir','operation-delete-entry','small ghost',`data-kind="${key}" data-id="${esc(x.id)}"`)}</div></div>${key==='creatures'&&x.element?`<span class="operation-record-meta">${esc(x.element)} ${x.vd?`· VD ${esc(x.vd)}`:''}</span>`:''}${key==='npcs'&&x.role?`<span class="operation-record-meta">${esc(x.role)}${x.disposition?` · ${esc(x.disposition)}`:''}</span>`:''}<p>${esc(x.body||'Sem descrição registrada.')}</p>${href?`<a class="operation-reference" href="${esc(href)}" target="_blank" rel="noopener">Abrir referência ↗</a>`:''}</div></article>`;}).join('')}</div>`:`<div class="panel operation-empty"><span class="operation-empty-mark">◇</span><h3>Nenhum registro em ${label.toLocaleLowerCase('pt-BR')}</h3><p>Use estes registros para manter as informações importantes desta operação junto do grupo.</p></div>`}`;
}
function editOperation(id){
 const current=campaignCurrent(),local=campaignLocal();if(!current||!local)return;
 const operations=operationEntries(current,'operations'),existing=operations.find(x=>x.id===id),isNew=!existing;
 const op=existing||{id:uid(),title:'',code:`OP-${String(operations.length+1).padStart(3,'0')}`,location:'',date:'',risk:'Moderado',status:'Planejada',master:'',summary:'',agentIds:[],objectives:[],clues:[],npcs:[],creatures:[],documents:[],timeline:[]};
 const crew=[...(local.agents||[]).map(agentId=>{const a=state.agents.find(x=>x.id===agentId);return a?{id:'agent:'+a.id,name:a.name,meta:`${a.class} · NEX ${a.nex}%`,label:`${a.name} · ${a.class}`,checked:(op.agentIds||[]).includes('agent:'+a.id)}:null;}).filter(Boolean),...(current.roster||[]).map(p=>({id:'member:'+p.id,name:p.agent||p.name,meta:`Jogador: ${p.name}`,label:`${p.agent||p.name} · jogador ${p.name}`,checked:(op.agentIds||[]).includes('member:'+p.id)}))];
 modal(isNew?'Nova operação':'Editar operação',`<div class="form-grid">${field('title','Nome da missão',op.title,'text','required maxlength="120"')}${field('code','Código do caso',op.code,'text','maxlength="40"')}${field('location','Local',op.location,'text','maxlength="160"')}${field('date','Data da missão',op.date,'date')}${select('risk','Grau de risco',['Baixo','Moderado','Alto','Extremo'],op.risk||'Moderado')}${select('status','Status',['Planejada','Em andamento','Concluída','Arquivada'],op.status||'Planejada')}${field('master','Mestre responsável',op.master||'','text','maxlength="80"')}<label class="field full">Resumo / briefing<textarea name="summary" rows="5" maxlength="5000" placeholder="O que os agentes sabem antes de começar?">${esc(op.summary||'')}</textarea></label><div class="full"><h3>Agentes envolvidos</h3><p class="hint">A equipe fica registrada junto desta operação para todos os participantes.</p><div class="operation-crew-pick">${crew.map(x=>check(`crew-${x.id.replace(':','-')}`,esc(x.label),x.checked)).join('')||'<p class="hint">Adicione agentes ou participantes à campanha primeiro.</p>'}</div></div><label class="field full">Objetivos · um por linha<textarea name="objectives" rows="5" maxlength="6000" placeholder="Encontrar a origem do sinal\nIdentificar quem abriu a Membrana">${esc((op.objectives||[]).map(x=>x.text).join('\n'))}</textarea></label></div>`,f=>{
  const title=String(f.get('title')||'').trim();if(!title)throw Error('Informe o nome da operação.');
  const choices=crew.filter(x=>f.has(`crew-${x.id.replace(':','-')}`)).map(x=>x.id);
  const lines=String(f.get('objectives')||'').split(/\r?\n/).map(x=>x.trim().slice(0,300)).filter(Boolean).slice(0,60);
  activeOperationId=op.id;campaignTab='operacoes';operationTab='overview';
  campaignMutate(c=>{c.operations=c.operations||[];let target=c.operations.find(x=>x.id===op.id);if(!target){target=op;c.operations.unshift(target);}const old=new Map((target.objectives||[]).map(x=>[x.text.toLocaleLowerCase('pt-BR'),x]));Object.assign(target,{title,code:String(f.get('code')||'').trim(),location:String(f.get('location')||'').trim(),date:String(f.get('date')||''),risk:String(f.get('risk')),status:String(f.get('status')),master:String(f.get('master')||'').trim(),summary:String(f.get('summary')||'').trim(),agentIds:choices,crew:crew.filter(x=>choices.includes(x.id)).map(x=>({id:x.id,name:x.name,meta:x.meta})),objectives:lines.map(text=>{const prev=old.get(text.toLocaleLowerCase('pt-BR'));return prev||{id:uid(),text,done:false};})});});
 });
}
function editOperationEntry(key,id){
 const c=campaignCurrent(),op=operationEntries(c,'operations').find(x=>x.id===activeOperationId);if(!op)return;
 const list=operationEntries(op,key),existing=list.find(x=>x.id===id),isNew=!existing,x=existing||{id:uid(),title:'',body:'',status:'',source:'',role:'',disposition:'',element:'',vd:0,when:'',reference:''};
 const fields=key==='clues'?`${field('source','Origem / local encontrado',x.source,'text','maxlength="140"')}${select('status','Estado da pista',['Não analisada','Analisada','Confirmada','Descartada'],x.status||'Não analisada')}`:key==='npcs'?`${field('role','Papel na investigação',x.role,'text','maxlength="100"')}${select('disposition','Disposição',['Desconhecida','Aliado','Neutro','Hostil'],x.disposition||'Desconhecida')}`:key==='creatures'?`${select('element','Elemento',['Desconhecido','Sangue','Morte','Conhecimento','Energia','Medo','Outro'],x.element||'Desconhecido')}${field('vd','VD (opcional)',x.vd||'','number','min="0" max="9999"')}${select('status','Estado',['Não identificada','Ativa','Contida','Derrotada','Desaparecida'],x.status||'Ativa')}`:key==='documents'?`${select('source','Tipo de documento',['Relatório','Foto','Áudio','Vídeo','Mapa','Registro','Outro'],x.source||'Relatório')}${select('status','Acesso',['Público para a mesa','Restrito','Confidencial'],x.status||'Público para a mesa')}${field('reference','Link externo (opcional)',x.reference,'url','maxlength="500"')}`:`${field('when','Data do acontecimento',x.when,'date')}`;
 const titleLabel=key==='npcs'?'Nome do NPC':key==='creatures'?'Nome da criatura':key==='documents'?'Nome do documento':key==='timeline'?'Acontecimento':'Título da pista';
 modal(isNew?`Adicionar ${key==='npcs'?'NPC':key==='creatures'?'criatura':key==='documents'?'documento':key==='timeline'?'evento':'pista'}`:`Editar ${titleLabel.toLocaleLowerCase('pt-BR')}`,`<div class="form-grid">${field('title',titleLabel,x.title,'text','required maxlength="120"')}${fields}<label class="field full">${key==='timeline'?'Descrição do acontecimento':'Descrição / observações'}<textarea name="body" rows="6" maxlength="1500">${esc(x.body||'')}</textarea></label></div>`,f=>{
  const title=String(f.get('title')||'').trim();if(!title)throw Error(`Informe ${key==='npcs'?'o nome do NPC':key==='creatures'?'o nome da criatura':key==='documents'?'o nome do documento':key==='timeline'?'o acontecimento':'o título da pista'}.`);
  campaignMutate(campaign=>{const target=campaign.operations?.find(v=>v.id===activeOperationId);if(!target)return;target[key]=target[key]||[];let entry=target[key].find(v=>v.id===id);if(!entry){entry=x;target[key].unshift(entry);}Object.assign(entry,{title,body:String(f.get('body')||'').trim(),source:String(f.get('source')||''),status:String(f.get('status')||''),role:String(f.get('role')||''),disposition:String(f.get('disposition')||''),element:String(f.get('element')||''),vd:Number(f.get('vd'))||0,when:String(f.get('when')||''),reference:String(f.get('reference')||'').trim()});});
 });
}
function importOperationThreat(){
 const threats=[...officialThreats,...state.threats,...state.homebrew.filter(x=>x.type==='Ameaças')];if(!threats.length)return toast('Não há ameaças no catálogo para vincular.');
 modal('Vincular ameaça do catálogo',`<label class="field full">Ameaça<select name="threat">${threats.map((x,i)=>`<option value="${i}">${esc(x.name)} · ${esc(x.element||'Elemento desconhecido')} · VD ${esc(x.vd||'—')}</option>`).join('')}</select></label><p class="hint">A ameaça entra como registro da operação; editar o caso não altera o catálogo.</p>`,f=>{const threat=threats[Number(f.get('threat'))];if(!threat)throw Error('Escolha uma ameaça.');campaignMutate(c=>{const op=c.operations?.find(x=>x.id===activeOperationId);if(!op)return;op.creatures=op.creatures||[];op.creatures.unshift({id:uid(),title:threat.name,body:threat.description||threat.actions||'',element:threat.element||'Desconhecido',vd:Number(threat.vd)||0,status:'Não identificada',source:threat.source||'Catálogo de ameaças'});});});
}
const clueStatuses=['Não analisada','Suspeita','Confirmada','Falsa','Resolvida'];
const clueTypes=['Documento','Depoimento','Objeto','Local','Registro digital','Vestígio','Outro'];
let clueStatusFilter='',clueCaseFilter='';
function campaignClues(c){
 const current=Array.isArray(c?.clues)?c.clues:[],seen=new Set(current.map(x=>x.id));
 const legacy=operationEntries(c,'operations').flatMap(op=>operationEntries(op,'clues').filter(x=>!seen.has(x.id)).map(x=>{seen.add(x.id);return{id:x.id,title:x.title,type:'Outro',description:x.body||'',location:x.source||'',foundBy:'',foundAt:'',operationId:op.id,status:x.status||'Não analisada',legacy:true};}));
 return [...current,...legacy];
}
function clueCaseLabel(c,id){return operationEntries(c,'operations').find(x=>x.id===id)?.title||'Sem caso vinculado';}
function clueCard(x,c){
 const local=campaignLocal(),secret=local?.isMaster!==false?local?.clueSecrets?.[x.id]:'';
 return `<article class="panel clue-card"><div class="clue-card-top"><span class="clue-status">${esc(x.status||'Não analisada')}</span><span class="eyebrow">${esc(x.type||'Outro')}</span></div><h3>${esc(x.title)}</h3><p>${esc(x.description||'Sem descrição registrada.')}</p><dl><div><dt>Caso</dt><dd>${esc(clueCaseLabel(c,x.operationId))}</dd></div><div><dt>Local</dt><dd>${esc(x.location||'—')}</dd></div><div><dt>Encontrada por</dt><dd>${esc(x.foundBy||'—')}</dd></div><div><dt>Data</dt><dd>${esc(x.foundAt||'—')}</dd></div></dl>${secret?`<details class="clue-secret"><summary>Nota reservada do mestre</summary><p>${esc(secret)}</p></details>`:''}<div class="actions">${button('Editar','clue-edit','small ghost',`data-id="${esc(x.id)}"`)}${button('Excluir','clue-delete','small ghost',`data-id="${esc(x.id)}"`)}</div></article>`;
}
function renderClueRegistry(local,c){
 const clues=campaignClues(c),operations=operationEntries(c,'operations'),filtered=clues.filter(x=>(!clueStatusFilter||x.status===clueStatusFilter)&&(!clueCaseFilter||x.operationId===clueCaseFilter));
 const filter=(name,label,options,value)=>`<label class="field">${label}<select data-clue-filter="${name}"><option value="">Todos</option>${options.map(([id,text])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`;
 return `<div class="clue-registry"><div class="operation-list-head"><div><span class="eyebrow">INVESTIGAÇÃO / EVIDÊNCIAS</span><h2>Sistema de Pistas</h2><p>Reúna as descobertas da campanha, acompanhe a análise e vincule cada pista a um caso.</p></div>${button('+ Nova pista','clue-add','small primary')}</div><div class="clue-filters">${filter('status','Status',clueStatuses.map(x=>[x,x]),clueStatusFilter)}${filter('case','Caso',operations.map(x=>[x.id,x.title]),clueCaseFilter)}<span>${filtered.length} de ${clues.length} pista${clues.length===1?'':'s'}</span></div>${filtered.length?`<div class="clue-grid">${filtered.map(x=>clueCard(x,c)).join('')}</div>`:`<div class="panel operation-empty"><span class="operation-empty-mark">⌕</span><h3>${clues.length?'Nenhuma pista corresponde aos filtros':'Nenhuma pista registrada'}</h3><p>${clues.length?'Altere o status ou caso selecionado para ver outras pistas.':'Adicione uma evidência para começar a investigação.'}</p></div>`}</div>`;
}
function renderOperationClues(op,c){
 const clues=campaignClues(c).filter(x=>x.operationId===op.id);
 return `<div class="operation-list-head"><div><span class="eyebrow">ARQUIVO DO CASO</span><h2>Pistas</h2><p>As evidências deste caso também aparecem no registro geral da campanha.</p></div>${button('+ Adicionar pista','operation-add-entry','small primary','data-kind="clues"')}</div>${clues.length?`<div class="clue-grid">${clues.map(x=>clueCard(x,c)).join('')}</div>`:`<div class="panel operation-empty"><span class="operation-empty-mark">⌕</span><h3>Nenhuma pista neste caso</h3><p>Registre a primeira evidência encontrada pela equipe.</p></div>`}`;
}
function editClue(id,defaultOperationId=''){
 const c=campaignCurrent(),local=campaignLocal();if(!c||!local)return;
 const old=campaignClues(c).find(x=>x.id===id),x=old||{id:uid(),title:'',type:'Documento',description:'',location:'',foundBy:'',foundAt:'',operationId:defaultOperationId,status:'Não analisada'};
 const cases=operationEntries(c,'operations'),statuses=clueStatuses.includes(x.status)?clueStatuses:[...clueStatuses,x.status];
 const caseSelect=`<label class="field">Caso relacionado<select name="operationId"><option value="">Sem caso vinculado</option>${cases.map(o=>`<option value="${esc(o.id)}" ${o.id===x.operationId?'selected':''}>${esc(o.title)}</option>`).join('')}</select></label>`;
 const secretField=local.isMaster!==false?`<label class="field full clue-secret-field">Informação secreta do mestre<textarea name="masterSecret" rows="4" maxlength="5000" placeholder="Hipóteses, revelações e informações que os jogadores ainda não sabem">${esc(local.clueSecrets?.[x.id]||'')}</textarea><small>Esta nota fica no seu arquivo pessoal e não é enviada à mesa compartilhada.</small></label>`:'';
 modal(id?'Editar pista':'Nova pista',`<div class="form-grid">${field('title','Título',x.title,'text','required maxlength="120"')}${select('type','Tipo',clueTypes.includes(x.type)?clueTypes:[...clueTypes,x.type],x.type)}${select('status','Status',statuses,x.status)}${field('location','Local onde foi encontrada',x.location||'','text','maxlength="160"')}${field('foundBy','Quem encontrou',x.foundBy||'','text','maxlength="120"')}${field('foundAt','Data',x.foundAt||'','date')}${caseSelect}<label class="field full">Descrição<textarea name="description" rows="6" maxlength="5000">${esc(x.description||'')}</textarea></label>${secretField}</div>`,f=>{
  const title=String(f.get('title')||'').trim();if(!title)throw Error('Informe o título da pista.');
  if(local.isMaster!==false){local.clueSecrets=local.clueSecrets||{};const note=String(f.get('masterSecret')||'').trim();if(note)local.clueSecrets[x.id]=note;else delete local.clueSecrets[x.id];save();}
  campaignMutate(target=>{target.clues=target.clues||[];let item=target.clues.find(v=>v.id===x.id);if(!item){item={id:x.id};target.clues.unshift(item);}Object.assign(item,{title,type:String(f.get('type')),description:String(f.get('description')||'').trim(),location:String(f.get('location')||'').trim(),foundBy:String(f.get('foundBy')||'').trim(),foundAt:String(f.get('foundAt')||''),operationId:String(f.get('operationId')||''),status:String(f.get('status'))});for(const op of target.operations||[])op.clues=(op.clues||[]).filter(v=>v.id!==x.id);});
 });
}
function deleteClue(id){modal('Excluir pista?','<p>A pista será removida da campanha e do caso relacionado.</p>',()=>{const local=campaignLocal();if(local?.clueSecrets)delete local.clueSecrets[id];save();campaignMutate(c=>{c.clues=(c.clues||[]).filter(x=>x.id!==id);for(const op of c.operations||[])op.clues=(op.clues||[]).filter(x=>x.id!==id);});});}
function operationsPageOverride(){
 const local=campaignLocal(),c=campaignCurrent();if(!local||!c)return campaignDetailBeforeOperations();
 if(location.hash.split('/')[2]==='mesa')return campaignDetailBeforeOperations();
 if(campaignTab==='operacoes'||campaignTab==='mural'||campaignTab==='pistas'||campaignTab==='documentos')return campaignOperationsPage(local,c,(local.agents||[]).map(id=>state.agents.find(a=>a.id===id)).filter(Boolean));
 const html=campaignDetailBeforeOperations();
 return html.replace(/(<div class="tabs campaign-subtabs">[\s\S]*?)(<\/div><div class="campaign-section">)/,(_,tabs,end)=>`${tabs}<button class="" data-action="campaign-section" data-tab="operacoes">Operações <small>${operationEntries(c,'operations').length}</small></button><button class="" data-action="campaign-section" data-tab="pistas">Pistas <small>${campaignClues(c).length}</small></button><button class="" data-action="campaign-section" data-tab="mural">Mural <small>${muralBoardList(local,c).length}</small></button><button class="" data-action="campaign-section" data-tab="documentos">Documentos <small>${campaignDocumentPool(c,local).length}</small></button>${end}`);
}
