const campaignDocumentTypes=['Relatório da Ordem','Jornal','Carta','Prontuário','Boletim policial','Documento confidencial','Outro'];
const campaignDocumentStyles=[['ordem','Arquivo da Ordem'],['jornal','Jornal antigo'],['carta','Carta pessoal'],['prontuario','Prontuário clínico'],['policial','Boletim policial'],['confidencial','Dossiê confidencial']];
let campaignDocumentImage='';
function safeCampaignDocumentImage(value){return /^data:image\/jpeg;base64,[A-Za-z0-9+/=]{1,32000}$/.test(String(value||''))?String(value):'';}
function campaignDocumentPool(c,local,operationId=''){
 const documents=Array.isArray(c?.documents)?c.documents.filter(x=>x&&x.private!==true):[];
 const legacy=operationEntries(c,'operations').flatMap(op=>operationEntries(op,'documents').filter(x=>x.private!==true).map(x=>({...x,operationId:x.operationId||op.id,legacyOperationId:op.id,documentType:x.documentType||x.source||'Outro'})));
 const all=[],seen=new Map();
 for(const item of [...documents,...legacy]){const id=String(item.id||'');if(!id)continue;const normalized={...item,id,title:item.title||'Documento sem título',documentType:campaignDocumentTypes.includes(item.documentType)?item.documentType:(campaignDocumentTypes.includes(item.source)?item.source:'Outro'),institution:item.institution||item.owner||'',issueDate:item.issueDate||item.when||'',signature:item.signature||'',stamp:item.stamp||'',style:campaignDocumentStyles.some(x=>x[0]===item.style)?item.style:'ordem',image:safeCampaignDocumentImage(item.image),reference:item.reference||'',status:item.status||'Público para a mesa',isProp:!!item.isProp,private:false,operationId:item.operationId||'',body:item.body||''};if(seen.has(id)){if(item.legacyOperationId)continue;all[seen.get(id)]=normalized;}else{seen.set(id,all.length);all.push(normalized);}}
 if(local&&local.isMaster!==false)for(const item of Array.isArray(local.documentPrivate)?local.documentPrivate:[]){if(!item||!item.id)continue;const normalized={...item,private:true,image:safeCampaignDocumentImage(item.image),style:campaignDocumentStyles.some(x=>x[0]===item.style)?item.style:'ordem'};if(seen.has(item.id))all[seen.get(item.id)]=normalized;else{seen.set(item.id,all.length);all.push(normalized);}}
 return operationId?all.filter(x=>x.operationId===operationId):all;
}
function campaignDocumentCaseName(c,id){return operationEntries(c,'operations').find(x=>x.id===id)?.title||'';}
function campaignDocumentStyleName(style){return campaignDocumentStyles.find(x=>x[0]===style)?.[1]||campaignDocumentStyles[0][1];}
function campaignDocumentParagraphs(body){return String(body||'').split(/\n{2,}/).map(x=>'<p>'+esc(x).replace(/\n/g,'<br>')+'</p>').join('')||'<p class="prop-placeholder">O conteúdo deste documento ainda não foi registrado.</p>';}
function renderGeneratedProp(doc){
 const style=campaignDocumentStyles.some(x=>x[0]===doc.style)?doc.style:'ordem';
 const image=safeCampaignDocumentImage(doc.image);
 return '<article class="generated-prop prop-'+style+'"><header class="prop-masthead"><div><span class="prop-institution">'+esc(doc.institution||'Arquivo LIMIAR')+'</span><h3>'+esc(doc.title||'Documento sem título')+'</h3><span class="prop-kind">'+esc(doc.documentType||'Documento')+' · '+esc(doc.issueDate||'Sem data')+'</span></div>'+(image?'<img class="prop-image" src="'+image+'" alt="Imagem anexada ao documento">':'')+'</header><div class="prop-rule"></div>'+(doc.stamp?'<span class="prop-stamp">'+esc(doc.stamp)+'</span>':'')+'<div class="prop-copy">'+campaignDocumentParagraphs(doc.body)+'</div>'+(doc.signature?'<footer class="prop-signature"><span class="prop-signature-mark">✒</span><span>'+esc(doc.signature)+'</span></footer>':'')+'<footer class="prop-footer"><span>'+esc(doc.status||'Público para a mesa')+'</span><span>ARQUIVO / '+esc(campaignDocumentStyleName(style))+'</span></footer></article>';
}
function renderCampaignDocumentCard(doc,c){
 const caseName=campaignDocumentCaseName(c,doc.operationId);
 const preview=doc.isProp?renderGeneratedProp(doc):'<div class="campaign-document-plain"><div class="document-plain-meta">'+esc(doc.documentType||'Documento')+' · '+esc(doc.issueDate||'Sem data')+'</div><p>'+esc(String(doc.body||'Sem conteúdo registrado.').slice(0,440))+(String(doc.body||'').length>440?'…':'')+'</p></div>';
 const actions=button('Editar','document-edit','small ghost','data-id="'+esc(doc.id)+'"')+(doc.isProp?button('Imprimir / salvar PDF','document-print','small primary','data-id="'+esc(doc.id)+'"'):button('Gerar prop','document-design','small primary','data-id="'+esc(doc.id)+'"'))+button('Excluir','document-delete','small ghost','data-id="'+esc(doc.id)+'"');
 return '<article class="panel campaign-document-card" data-document-search="'+esc((doc.title+' '+doc.documentType+' '+caseName).toLocaleLowerCase('pt-BR'))+'"><div class="campaign-document-card-top"><span class="eyebrow">'+esc(doc.documentType||'Documento')+(doc.isProp?' · PROP':'')+'</span><span class="campaign-document-status">'+esc(doc.private?'PRIVADO DO MESTRE':doc.status||'Público para a mesa')+'</span></div>'+(doc.isProp?preview:'<h3>'+esc(doc.title)+'</h3>'+preview)+'<div class="campaign-document-meta"><span>'+esc(caseName||'Sem operação vinculada')+'</span><span>'+esc(doc.institution||'Instituição não informada')+'</span></div><div class="actions">'+actions+'</div></article>';
}
function renderCampaignDocumentLibrary(local,c){
 const docs=campaignDocumentPool(c,local);
 return '<section class="campaign-document-library"><div class="operation-list-head"><div><span class="eyebrow">CAMPANHA / DOCUMENTOS E HANDOUTS</span><h2>Criador de documentos e props</h2><p>Escreva relatórios, cartas, jornais e registros. Transforme qualquer texto em um documento de campanha pronto para imprimir ou salvar como PDF.</p></div><div class="actions">'+button('+ Criar documento','document-add','small primary')+button('+ Gerar prop','document-create-prop','small ghost')+'</div></div><div class="document-library-note"><b>Confidencialidade:</b> o rótulo “Confidencial” aparece no documento. Para esconder o conteúdo dos jogadores, use “Somente o mestre pode ver” no editor.</div><label class="campaign-document-search"><span>⌕</span><input id="campaign-document-search" type="search" placeholder="Buscar por título, tipo ou operação…" aria-label="Buscar documentos"></label>'+(docs.length?'<div class="campaign-document-grid">'+docs.map(x=>renderCampaignDocumentCard(x,c)).join('')+'</div><p class="campaign-document-no-results" hidden>Nenhum documento corresponde à busca.</p>':'<div class="panel operation-empty"><span class="operation-empty-mark">▤</span><h3>Nenhum documento na campanha</h3><p>Crie um documento para a mesa ou gere um prop visual para entregar aos jogadores.</p><div class="actions">'+button('＋ Criar documento','document-add','small primary')+button('✧ Gerar primeiro prop','document-create-prop','small ghost')+'</div></div>')+'</section>';
}
function renderCampaignDocuments(op,c,local){
 const docs=campaignDocumentPool(c,local,op.id);
 return '<div class="campaign-operation-documents"><div class="operation-list-head"><div><span class="eyebrow">ARQUIVO DO CASO · '+esc(op.code||'OPERAÇÃO')+'</span><h2>Documentos da operação</h2><p>Crie registros e handouts vinculados a esta missão. Eles também aparecem na biblioteca de documentos da campanha.</p></div><div class="actions">'+button('+ Criar documento','document-add','small primary','data-operation="'+esc(op.id)+'"')+button('+ Gerar prop','document-create-prop','small ghost','data-operation="'+esc(op.id)+'"')+'</div></div>'+(docs.length?'<div class="campaign-document-grid">'+docs.map(x=>renderCampaignDocumentCard(x,c)).join('')+'</div>':'<div class="panel operation-empty"><span class="operation-empty-mark">▤</span><h3>Nenhum documento ligado a esta operação</h3><p>Crie um documento ou vincule um existente a este caso.</p><div class="actions">'+button('＋ Criar documento','document-add','small primary','data-operation="'+esc(op.id)+'"')+button('✧ Gerar prop','document-create-prop','small ghost','data-operation="'+esc(op.id)+'"')+'</div></div>')+'</div>';
}
function campaignDocumentDraftFromForm(form,id,existing){
 const title=String(form.get('title')||'').trim();
 if(!title)throw Error('Informe o título do documento.');
 const type=String(form.get('documentType')||'Outro'),operationId=String(form.get('operationId')||'');
 const validOperation=operationEntries(campaignCurrent(),'operations').some(x=>x.id===operationId);
 const isProp=form.get('format')==='prop',style=String(form.get('style')||'ordem');
 const issueDate=String(form.get('issueDate')||'').slice(0,40);
 return{id,title,documentType:campaignDocumentTypes.includes(type)?type:'Outro',institution:String(form.get('institution')||'').trim().slice(0,120),issueDate,status:String(form.get('status')||'Público para a mesa').slice(0,40),body:String(form.get('body')||'').trim().slice(0,10000),signature:String(form.get('signature')||'').trim().slice(0,100),stamp:String(form.get('stamp')||'').trim().slice(0,80),style:campaignDocumentStyles.some(x=>x[0]===style)?style:'ordem',image:safeCampaignDocumentImage(campaignDocumentImage||existing?.image),reference:safeOperationUrl(String(form.get('reference')||'').trim()),isProp,operationId:validOperation?operationId:'',private:form.has('documentPrivate'),created:existing?.created||new Date().toLocaleDateString('pt-BR')};
}
function editCampaignDocument(id='',forceProp=false,defaultOperationId=''){
 const local=campaignLocal(),c=campaignCurrent();
 if(!local||!c)return;
 const existing=id?campaignDocumentPool(c,local).find(x=>x.id===id):null;
 const x=existing||{id:uid(),title:'',documentType:'Relatório da Ordem',institution:'Ordem da Realidade',issueDate:new Date().toISOString().slice(0,10),status:'Público para a mesa',body:'',signature:'',stamp:'',style:'ordem',image:'',isProp:!!forceProp,operationId:defaultOperationId,private:false};
 campaignDocumentImage=safeCampaignDocumentImage(x.image);
 const operations=operationEntries(c,'operations');
 const caseOptions='<label class="field">Operação relacionada<select name="operationId"><option value="">Sem operação vinculada</option>'+operations.map(op=>'<option value="'+esc(op.id)+'" '+(op.id===x.operationId?'selected':'')+'>'+esc(op.title)+'</option>').join('')+'</select></label>';
 const privateField=local.isMaster!==false?'<div class="document-private-setting">'+check('documentPrivate','Somente o mestre pode ver',!!x.private)+'<small>Este registro fica no arquivo pessoal do mestre e não é enviado para a campanha compartilhada.</small></div>':'';
 const styleOptions=campaignDocumentStyles.map(s=>'<option value="'+s[0]+'" '+(s[0]===(x.style||'ordem')?'selected':'')+'>'+s[1]+'</option>').join('');
 const body='<div class="campaign-document-editor" id="campaign-document-editor"><p class="hint">O texto é guardado como texto simples. O LIMIAR aplica o visual escolhido e mantém os controles da campanha separados do documento.</p><div class="form-grid">'+field('title','Título',x.title,'text','required maxlength="120"')+select('documentType','Tipo de documento',campaignDocumentTypes,x.documentType||'Outro')+caseOptions+field('institution','Instituição / origem',x.institution||'','text','maxlength="120"')+field('issueDate','Data',x.issueDate||'','date')+select('status','Classificação exibida',['Público para a mesa','Restrito','Confidencial'],x.status||'Público para a mesa')+'<label class="field">Formato<select name="format"><option value="document" '+(!x.isProp?'selected':'')+'>Documento de texto</option><option value="prop" '+(x.isProp?'selected':'')+'>Prop visual para a mesa</option></select></label><label class="field">Estilo do prop<select name="style">'+styleOptions+'</select></label><label class="field full">Conteúdo<textarea name="body" rows="10" maxlength="10000" placeholder="Escreva o conteúdo completo do documento…">'+esc(x.body||'')+'</textarea></label><label class="field">Assinatura<input name="signature" value="'+esc(x.signature||'')+'" maxlength="100" placeholder="Nome, cargo ou assinatura"></label><label class="field">Carimbo / selo<input name="stamp" value="'+esc(x.stamp||'')+'" maxlength="80" placeholder="Ex.: ACESSO RESTRITO"></label><label class="field full">Imagem opcional<input name="imageFile" type="file" accept="image/png,image/jpeg,image/webp"><small>A imagem é reduzida antes de ser salva na campanha.</small></label><div class="document-image-preview" data-document-image-preview '+(campaignDocumentImage?'':'hidden')+'>'+(campaignDocumentImage?'<img src="'+campaignDocumentImage+'" alt="Prévia da imagem anexada">':'<img src="" alt="Prévia da imagem anexada">')+button('Remover imagem','document-remove-image','small ghost')+'</div>'+field('reference','Link de referência (opcional)',x.reference||'','url','maxlength="500" placeholder="https://…')+privateField+'</div><div class="document-preview-heading"><span class="eyebrow">PRÉVIA DO DOCUMENTO</span><span class="meta">Atualizada enquanto você escreve</span></div><div class="campaign-document-preview" data-document-preview></div></div>';
 modal(existing?(x.isProp?'Editar prop':'Editar documento'):(forceProp?'Gerador de props':'Criador de documentos'),body,form=>{
  const draft=campaignDocumentDraftFromForm(form,x.id,x);
  if(!draft.private&&(!existing||existing.private)&&campaignDocumentPool(c,local).filter(v=>!v.private).length>=100)throw Error('A campanha já atingiu o limite de 100 documentos públicos.');
  if(draft.private&&local.isMaster===false)throw Error('Somente o mestre pode criar documentos privados.');
  if(draft.private){local.documentPrivate=Array.isArray(local.documentPrivate)?local.documentPrivate:[];local.documentPrivate=[draft,...local.documentPrivate.filter(v=>v.id!==draft.id)];save();}
  else{local.documentPrivate=Array.isArray(local.documentPrivate)?local.documentPrivate.filter(v=>v.id!==draft.id):[];save();}
  campaignMutate(target=>{
   target.documents=Array.isArray(target.documents)?target.documents:[];
   target.documents=target.documents.filter(v=>v.id!==draft.id);
   for(const op of target.operations||[])op.documents=(op.documents||[]).filter(v=>v.id!==draft.id);
   if(!draft.private)target.documents.unshift(draft);
  });
 });
 updateCampaignDocumentPreview();
}
async function compressCampaignDocumentImage(file){
 if(!file||file.size>8*1024*1024)throw Error('A imagem precisa ter até 8 MB.');
 if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Use uma imagem JPG, PNG ou WebP.');
 const url=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||''));reader.onerror=()=>reject(Error('Não foi possível ler a imagem.'));reader.readAsDataURL(file);});
 const image=await new Promise((resolve,reject)=>{const picture=new Image();picture.onload=()=>resolve(picture);picture.onerror=()=>reject(Error('Não foi possível abrir a imagem.'));picture.src=url;});
 let width=image.naturalWidth,height=image.naturalHeight;
 const scale=Math.min(1,480/width,360/height);width=Math.max(1,Math.round(width*scale));height=Math.max(1,Math.round(height*scale));
 const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;
 const context=canvas.getContext('2d');if(!context)throw Error('O navegador não conseguiu preparar a imagem.');
 context.fillStyle='#f7f2e8';context.fillRect(0,0,width,height);context.drawImage(image,0,0,width,height);
 for(const quality of [.82,.72,.62,.52,.42]){const result=canvas.toDataURL('image/jpeg',quality);if(result.length<=32000)return result;}
 canvas.width=Math.max(1,Math.round(width*.65));canvas.height=Math.max(1,Math.round(height*.65));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);
 const smaller=canvas.toDataURL('image/jpeg',.42);if(smaller.length<=32000)return smaller;
 throw Error('A imagem ainda ficou grande demais. Escolha uma imagem menor.');
}
function updateCampaignDocumentPreview(){
 const form=document.querySelector('#modalform'),preview=form?.querySelector('[data-document-preview]');if(!form||!preview)return;
 const data=new FormData(form),style=String(data.get('style')||'ordem');
 const draft={title:String(data.get('title')||'Prévia do documento'),documentType:String(data.get('documentType')||'Documento'),institution:String(data.get('institution')||''),issueDate:String(data.get('issueDate')||''),status:String(data.get('status')||'Público para a mesa'),body:String(data.get('body')||''),signature:String(data.get('signature')||''),stamp:String(data.get('stamp')||''),style:campaignDocumentStyles.some(x=>x[0]===style)?style:'ordem',image:campaignDocumentImage};
 const prop=data.get('format')==='prop';
 preview.innerHTML=prop?renderGeneratedProp(draft):'<article class="document-preview-plain"><div><span>'+esc(draft.documentType)+' · '+esc(draft.issueDate||'Sem data')+'</span><h3>'+esc(draft.title)+'</h3><small>'+esc(draft.institution||'Instituição não informada')+'</small></div><div class="document-preview-copy">'+campaignDocumentParagraphs(draft.body)+'</div><footer>'+esc(draft.status)+'</footer></article>';
 const container=form.querySelector('[data-document-image-preview]');if(container){container.hidden=!campaignDocumentImage;if(campaignDocumentImage)container.querySelector('img').src=campaignDocumentImage;}
}
function printCampaignDocument(id){
 const local=campaignLocal(),c=campaignCurrent(),doc=campaignDocumentPool(c,local).find(x=>x.id===id);
 if(!doc)return toast('Documento não encontrado.');
 const win=window.open('about:blank','_blank');if(!win)return toast('Permita a janela de impressão para salvar o prop como PDF.');
 const css='@page{size:A4;margin:18mm}*{box-sizing:border-box}body{margin:0;background:#ddd;font:15px/1.65 Georgia,serif;color:#26241f}.generated-prop{position:relative;max-width:780px;min-height:900px;margin:24px auto;padding:44px 48px;background:#f4f0e6;border:1px solid #b7aa91;box-shadow:0 12px 35px #0002}.prop-masthead{display:flex;justify-content:space-between;gap:24px;align-items:flex-start}.prop-institution,.prop-kind,.prop-footer{font:700 10px/1.5 Arial,sans-serif;letter-spacing:.13em;text-transform:uppercase;color:#5c5549}.prop-masthead h3{font:700 28px/1.2 Georgia,serif;margin:8px 0}.prop-image{width:150px;max-height:170px;object-fit:cover;border:5px solid #fff;box-shadow:0 2px 8px #0002}.prop-rule{height:3px;margin:22px 0 26px;background:#897c65}.prop-copy{font-size:15px;line-height:1.8;white-space:normal}.prop-copy p{margin:0 0 14px}.prop-stamp{display:inline-block;border:2px solid #8d3433;color:#8d3433;padding:6px 12px;font:bold 12px Arial,sans-serif;letter-spacing:.12em;text-transform:uppercase;transform:rotate(-4deg);margin:0 0 18px}.prop-signature{margin:56px 0 26px;border-top:1px solid #8c8478;padding-top:9px;width:55%;font-style:italic}.prop-footer{display:flex;justify-content:space-between;gap:12px;border-top:1px solid #b7aa91;padding-top:12px;margin-top:40px}.prop-jornal{background:#f5f0df;border:4px double #423a2d;font-family:Georgia,serif}.prop-jornal .prop-masthead h3{text-align:center;text-transform:uppercase;font-size:36px}.prop-jornal .prop-rule{background:#292720}.prop-carta{background:#f3eee4;border-color:#887a65}.prop-carta .prop-rule{background:#7b5950;height:1px}.prop-prontuario{background:#eef4f2;border-color:#7c9b9b;font-family:Arial,sans-serif}.prop-prontuario .prop-rule{background:#4b8583}.prop-policial{background:#f0e7d4;border-color:#9a7848}.prop-policial .prop-stamp{color:#993d37;border-color:#993d37}.prop-confidencial{background:#eee9e1;border:3px solid #6e282c}.prop-confidencial .prop-stamp{color:#a42e32;border-color:#a42e32}.prop-ordem{background:#f1eddf;border-color:#a59062}.prop-ordem .prop-rule{background:#9b8652}@media print{body{background:#fff}.generated-prop{margin:0 auto;box-shadow:none;break-inside:avoid;min-height:0}.prop-stamp{print-color-adjust:exact;-webkit-print-color-adjust:exact}}';
 win.document.open();win.document.write('<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(doc.title)+' · LIMIAR</title><style>'+css+'</style></head><body>'+renderGeneratedProp(doc)+'</body></html>');win.document.close();setTimeout(()=>{win.focus();win.print();},350);
}
function deleteCampaignDocument(id){
 const local=campaignLocal(),c=campaignCurrent(),doc=campaignDocumentPool(c,local).find(x=>x.id===id);if(!doc)return;
 modal('Excluir documento?','<p>“'+esc(doc.title)+'” será removido da campanha.</p>',()=>{
  if(doc.private){local.documentPrivate=(local.documentPrivate||[]).filter(x=>x.id!==id);save();render();}
  else campaignMutate(target=>{target.documents=(target.documents||[]).filter(x=>x.id!==id);for(const op of target.operations||[])op.documents=(op.documents||[]).filter(x=>x.id!==id);});
 });
}
function documentStudioAction(e){
 const b=e.target.closest?.('[data-action]');if(!b)return;
 const action=b.dataset.action,id=b.dataset.id||'',operation=b.dataset.operation||'';
 if(action==='operation-add-entry'&&b.dataset.kind==='documents'){e.preventDefault();e.stopImmediatePropagation();editCampaignDocument('',false,activeOperationId);return;}
 if(action==='operation-edit-entry'&&b.dataset.kind==='documents'){e.preventDefault();e.stopImmediatePropagation();editCampaignDocument(id);return;}
 if(action==='operation-delete-entry'&&b.dataset.kind==='documents'){e.preventDefault();e.stopImmediatePropagation();deleteCampaignDocument(id);return;}
 if(action==='document-add'){e.preventDefault();e.stopImmediatePropagation();editCampaignDocument('',false,operation);return;}
 if(action==='document-create-prop'){e.preventDefault();e.stopImmediatePropagation();editCampaignDocument('',true,operation);return;}
 if(action==='document-edit'){e.preventDefault();e.stopImmediatePropagation();editCampaignDocument(id);return;}
 if(action==='document-design'){e.preventDefault();e.stopImmediatePropagation();editCampaignDocument(id,true);return;}
 if(action==='document-delete'){e.preventDefault();e.stopImmediatePropagation();deleteCampaignDocument(id);return;}
 if(action==='document-print'){e.preventDefault();e.stopImmediatePropagation();printCampaignDocument(id);return;}
 if(action==='document-remove-image'){e.preventDefault();e.stopImmediatePropagation();campaignDocumentImage='';updateCampaignDocumentPreview();return;}
}
document.addEventListener('click',documentStudioAction,true);
document.addEventListener('input',e=>{if(e.target.closest?.('#campaign-document-editor'))updateCampaignDocumentPreview();if(e.target.matches?.('#campaign-document-search'))filterCampaignDocuments(e.target.value);});
document.addEventListener('change',async e=>{
 const editor=e.target.closest?.('#campaign-document-editor');if(!editor)return;
 if(e.target.name==='imageFile'&&e.target.files?.[0]){try{campaignDocumentImage=await compressCampaignDocumentImage(e.target.files[0]);updateCampaignDocumentPreview();}catch(error){campaignDocumentImage='';e.target.value='';updateCampaignDocumentPreview();toast(error.message||'Não foi possível anexar a imagem.');}return;}
 updateCampaignDocumentPreview();
});
function filterCampaignDocuments(value){
 const query=String(value||'').toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();let shown=0;
 for(const card of document.querySelectorAll('.campaign-document-card')){const hay=(card.dataset.documentSearch||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'');card.hidden=!!query&&!hay.includes(query);if(!card.hidden)shown++;}
 const empty=document.querySelector('.campaign-document-no-results');if(empty)empty.hidden=shown!==0;
}
const renderOperationBeforeDocumentStudio=renderOperation;
renderOperation=function(op,c,local){
 const html=renderOperationBeforeDocumentStudio(op,c,local),count=campaignDocumentPool(c,local,op.id).length;
 return html.replace(/(<button[^>]*data-tab="documents">Documentos)(?: <small>\d+<\/small>)?/,(_,prefix)=>prefix+' <small>'+count+'</small>').replace(/(<button data-action="operation-tab" data-tab="documents"><b>)\d+(<\/b><span>Documentos<\/span>)/,(_,a,b)=>a+count+b);
};
const renderOperationRecordsBeforeDocumentStudio=renderOperationRecords;
renderOperationRecords=function(op,key){if(key==='documents')return renderCampaignDocuments(op,campaignCurrent(),campaignLocal());return renderOperationRecordsBeforeDocumentStudio(op,key);};
const campaignOperationsPageBeforeDocumentStudio=campaignOperationsPage;
campaignOperationsPage=function(local,c,agents){
 if(campaignTab!=='documentos')return campaignOperationsPageBeforeDocumentStudio(local,c,agents).replace('</div><div class="campaign-section operation-section">','<button class="'+(campaignTab==='documentos'?'active':'')+'" data-action="campaign-section" data-tab="documentos">Documentos <small>'+campaignDocumentPool(c,local).length+'</small></button></div><div class="campaign-section operation-section">');
 let html=campaignOperationsPageBeforeDocumentStudio(local,c,agents);
 html=html.replace('</div><div class="campaign-section operation-section">','<button class="active" data-action="campaign-section" data-tab="documentos">Documentos <small>'+campaignDocumentPool(c,local).length+'</small></button></div><div class="campaign-section operation-section">');
 return html.replace(/<div class="campaign-section operation-section">[\s\S]*<\/div><\/div>$/, '<div class="campaign-section operation-section">'+renderCampaignDocumentLibrary(local,c)+'</div></div>');
};
const renderUpdatesBeforeDocumentStudio=renderUpdates;
renderUpdates=function(){
 const cards='<article class="panel update-card"><div class="update-card-head"><span class="update-card-mark">▤</span><span class="eyebrow">CAMPANHAS / AUTORIA</span></div><h2>Criador de documentos</h2><p>Escreva relatórios da Ordem, jornais, cartas, prontuários, boletins policiais e documentos de campanha. Organize cada registro por tipo, data, instituição e operação relacionada.</p><div class="update-note">Notas marcadas como privadas ficam somente no arquivo do mestre.</div></article><article class="panel update-card"><div class="update-card-head"><span class="update-card-mark">✧</span><span class="eyebrow">CAMPANHAS / IMERSÃO</span></div><h2>Gerador de props</h2><p>Transforme o texto em um handout visual com estilo temático, imagem, assinatura e carimbo. Pré-visualize e imprima ou salve como PDF.</p><div class="update-note">Os rótulos de classificação são visuais; a privacidade do mestre é controlada separadamente.</div></article>';
 return renderUpdatesBeforeDocumentStudio().replace('</div><div class="updates-footnote">',cards+'</div><div class="updates-footnote">');
};
